An order book is a data structure that keeps track of the buy and sell orders for a financial instrument, such as a stock or a currency. The order book is organized by price, with the highest buy order at the top and the highest sell order at the bottom. Here is some example C code that demonstrates how to implement a limit order book:

```c
#include <stdio.h>
#include <stdlib.h>

// Define the struct for the order book
typedef struct {
    double price; // the price of the financial instrument
    double size; // the number of shares/units available
    double total_size; // the total number of shares/units available
    char status; // either 'B' for buy or 'S' for sell
} Order;

// Define the functions to manipulate the order book
void add_buy_order(Order* book, double price, double size) {
    // check if there is enough size available
    if (book->total_size - book->size < size) {
        printf("Not enough size available\n");
        exit(1);
    }

    // add the buy order to the end of the book
    Order new_order = {price, size, book->total_size - book->size, 'B'};
    order_find_by_price(book, price);
    book->size -= size;
    book->total_size += size;
    printf("Buy order added at price %f for %d shares\n", price, size);
}

void add_sell_order(Order* book, double price, double size) {
    // check if there is enough size available
    if (book->total_size - book->size < size) {
        printf("Not enough size available\n");
        exit(1);
    }

    // add the sell order to the end of the book
    Order new_order = {price, size, book->total_size - book->size, 'S'};
    order_find_by_price(book, price);
    book->size -= size;
    book->total_size += size;
