}

// Find the first buy or sell order in the book
Order* order_find_by_price(Order* book, double price) {
    double total_size = 0;
    Order* current = book;

    while (current->price != price) {
        if (current->price < price) {
            total_size += current->size;
        }
        current = current->next;
    }
    // check if there is enough size available
    if (current->size < size) {
        printf("Not enough size available\n");
        exit(1);
    }
