}
```
3. Define a function that runs the fuzzer by sending random requests and printing the responses:
```scss
func RunFuzzer(numRequests int) {
    // keep track of the requests and responses
    requests := make(map[string][]byte)
    responses := make(map[string]error)

    // send random requests and record the responses
    for i := 0; i < numRequests; i++ {
        url := fmt.Sprintf("http://example.com/api/endpoint")
        bodyType := "malicious"
        body, err := SendMaliciousRequest(url, bodyType)
        if err != nil {
            responses[url] = err
            continue
        }
        requests[url] = body
        fmt.Println("Request sent:", url)
        fmt.Println("Response received:", string(body))
    }

    // print the results
    printResults(requests, responses)
}
```
4. Define a function that prints the results:
```less
func printResults(requests map[string][]byte, responses map[string]error) {
    // print the requests and responses
    for url, body := range requests {
        response := responses[url]
        if response != nil {
            fmt.Println(url, ":", response)
            continue
        }
        fmt.Println(url, ":", string(body))
    }
}
```
